#include <cstdio>
#include <cctype>
int countV(char *s, int n) {
    int cnt = 0;
    for (int i = 0; i < n; i++) {
        char c = tolower(s[i]);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') cnt++;
    }
    return cnt;
}
int main() {
    char s[100005];
    int n = 0, c;
    while ((c = getchar()) != '\n' && c != EOF) s[n++] = c;
    printf("%d\n", countV(s, n));
    return 0;
}

