#include <iostream>
#include <sstream>
#include <string>
using namespace std;
int split(string line, string v[]) {
    istringstream in(line);
    string w;
    int k = 0;
    while (in >> w) v[k++] = w;
    return k;
}
int main() {
    string line, v[1005];
    getline(cin, line);
    int k = split(line, v);
    for (int i = k - 1; i >= 0; i--) {
        cout << v[i];
        if (i > 0) cout << " ";
    }
    cout << endl;
    return 0;
}

