#include <iostream>
using namespace std;
int a[105][105];
int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> a[i][j];
    int total = 0;
    for (int i = 0; i < n; i++) {
        int rs = 0;
        for (int j = 0; j < m; j++) rs += a[i][j];
        cout << rs << endl;
        total += rs;
    }
    for (int j = 0; j < m; j++) {
        int cs = 0;
        for (int i = 0; i < n; i++) cs += a[i][j];
        cout << cs << " ";
    }
    cout << endl << total << endl;
    return 0;
}

