#include <cstdio>
int a[505][505];
long long diag(int n, int anti) {
    long long s = 0;
    for (int i = 0; i < n; i++) {
        if (anti) s += a[i][n - 1 - i];
        else s += a[i][i];
    }
    return s;
}
int main() {
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf("%d", &a[i][j]);
    printf("%lld %lld\n", diag(n, 0), diag(n, 1));
    return 0;
}

