#include <iostream>
#include <string>
using namespace std;
void printFreq(string s) {
    int freq[26] = {0};
    for (int i = 0; i < (int)s.size(); i++) freq[s[i] - 'a']++;
    for (int i = 0; i < 26; i++)
        if (freq[i] > 0) cout << (char)('a' + i) << " " << freq[i] << "\n";
}
int main() {
    string s;
    cin >> s;
    printFreq(s);
    return 0;
}

