using namespace std;
int main() {
    int n, k;
    cin >> n >> k;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    k %= n;
    for (int i = 0; i < n; i++) {
        int j = i + k;
        if (j >= n) j -= n;
        b[i] = a[j];
    }
    for (int i = 0; i < n; i++) cout << b[i] << (i + 1 < n ? " " : "\n");
    return 0;
}

