#include <cstdio>
#include <cstring>
#include <cctype>
bool isPal(char *s) {
    int i = 0, j = strlen(s) - 1;
    int bad = 0;
    while (i < j) {
        if (tolower(s[i]) != tolower(s[j])) bad++;
        i++;
        j--;
    }
    return bad == 0;
}
int main() {
    char s[100005];
    scanf("%s", s);
    puts(isPal(s) ? "YES" : "NO");
    return 0;
}

