#include <iostream>
#include <vector>
using namespace std;
int rowSum(vector<int>& r) {
    int s = 0;
    for (int x : r) s += x;
    return s;
}
int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> a(n, vector<int>(m));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) cin >> a[i][j];
    int sums[105];
    for (int i = 0; i < n; i++) sums[i] = rowSum(a[i]);
    int bi = 0;
    for (int i = 1; i < n; i++)
        if (sums[i] > sums[bi]) bi = i;
    cout << bi + 1 << " " << sums[bi] << "\n";
    return 0;
}

